import type { LessonBlueprint } from "./course-curriculum";

type Deep = {
  id: string; module: string; title: string; language: string; objective: string; explanation: string;
  flow: [string, string, string]; example: string; note: string; starter: string; task: string;
  marker: string; checks: [string, string];
};

function teach(item: Deep): LessonBlueprint {
  const diagram = item.flow.join("\n       ↓\n");
  return {
    id: item.id, module: item.module, title: item.title, language: item.language, objective: item.objective,
    explanation: item.explanation, duration: 38, practice: true,
    visualSteps: item.flow,
    systemDiagram: { title: "So greifen die Teile ineinander", diagram, note: item.note },
    examples: [{ title: "Im Projekt", code: item.example, note: item.note, language: item.language }],
    starterCode: item.starter, task: item.task, successPattern: new RegExp(item.marker, "i"),
    projectSteps: [item.flow[0], item.flow[1], item.flow[2], `Prüfe: ${item.checks[0]}`],
    acceptanceCriteria: item.checks,
    takeaway: item.objective,
  };
}

