const backend: Deep[] = [
  { id: "http-lifecycle", module: "10 · HTTP verstehen", title: "Anfrage und Antwort vollständig verfolgen", language: "plaintext", objective: "Du erklärst Methode, Pfad, Header, Body und Status an einer eigenen API.", explanation: "Eine HTTP-Anfrage trägt Methode und Pfad, optional Header und Daten. Express ordnet sie einer Route zu; die Antwort enthält Status, Header und Daten. Zeichne diesen Weg für GET und POST mit einem Erfolgs- und Fehlerfall.", flow: ["Client sendet Anfrage", "Express wählt Route", "Antwort mit Status + JSON"], example: "POST /tasks\nContent-Type: application/json\n{\"title\":\"Lernen\"} → 201 + neue Aufgabe", note: "GET liest, POST erzeugt hier einen neuen Datensatz; der Status beschreibt das Ergebnis.", starter: "Anfrage: \nRoute: \nErfolgsantwort: \nFehlerantwort: \n", task: "Dokumentiere GET /tasks und POST /tasks mit Methode, Pfad, Eingabe und zwei Statusfällen.", marker: "Anfrage:|Route:", checks: ["Anfrage und Antwort sind getrennt.", "Status 201 und Fehlerstatus sind begründet."] },
  { id: "express-middleware", module: "11 · Express beherrschen", title: "Middleware und Reihenfolge praktisch prüfen", language: "javascript", objective: "Du erkennst, wie eine Anfrage durch mehrere Express-Funktionen läuft.", explanation: "Middleware ist eine Funktion zwischen Eingang und Route. express.json liest JSON, eigene Middleware kann eine Anfrage markieren oder abweisen. Die Registrierungsreihenfolge entscheidet, welche Funktion zuerst läuft.", flow: ["express.json()", "Prüfung mit next()", "Route oder Fehler"], example: "app.use(express.json());\napp.use((req, _res, next) => { req.startedAt = Date.now(); next(); });", note: "Ohne next oder Antwort bleibt eine Anfrage hängen; teste deshalb auch einen abgewiesenen Fall.", starter: "app.use(express.json());\n// eigene Middleware ergänzen\n", task: "Ergänze eine Middleware, die eine Anfrage markiert, und eine, die fehlende Eingaben abweist. Prüfe die Reihenfolge.", marker: "app\\.use|next\\(", checks: ["Gültige Anfrage erreicht die Route.", "Abgewiesene Anfrage erhält eine Antwort."] },
  { id: "express-router", module: "11 · Express beherrschen", title: "Routen in ein eigenes Modul auslagern", language: "javascript", objective: "Du trennst Aufgabenrouten vom Start der Anwendung.", explanation: "Express Router bündelt Routen unter einem gemeinsamen Pfad. app.js registriert den Router; server.js startet den Port. So lässt sich die Aufgabenfunktion ohne große Startdatei weiterentwickeln.", flow: ["app.js", "Router /tasks", "GET und POST"], example: "const router = express.Router();\nrouter.get('/', listTasks);\nrouter.post('/', createTask);\napp.use('/tasks', router);", note: "Die Handler bleiben getrennt vom Registrieren der URL.", starter: "const router = express.Router();\n// GET und POST registrieren\n", task: "Lege tasks-router.js an und verschiebe GET /tasks sowie POST /tasks dorthin. Prüfe beide alten URLs erneut.", marker: "express\\.Router|router\\.get|router\\.post", checks: ["URLs bleiben nach dem Umbau gleich.", "server.js enthält keine Fachlogik."] },
  { id: "input-validation", module: "11 · Express beherrschen", title: "Eingaben an der API-Grenze validieren", language: "javascript", objective: "Du weist falsche JSON-Daten vor der Geschäftsregel zurück.", explanation: "Validierung prüft Form und Grenzen einer Eingabe. Ein fehlender Titel, Leerzeichen und eine zu lange Zeichenfolge sind unterschiedliche Fälle. Ein gültiger Titel wird erst nach der Prüfung an die Fachfunktion übergeben.", flow: ["req.body lesen", "Typ und Grenze prüfen", "400 oder Fachfunktion"], example: "function readTitle(body) {\n  if (typeof body?.title !== 'string') return null;\n  const title = body.title.trim();\n  return title.length > 0 && title.length <= 120 ? title : null;\n}", note: "trim entfernt Rand-Leerzeichen; die Längengrenze verhindert übergroße Eingaben.", starter: "function readTitle(body) {\n  // Typ, Leerfall und Länge prüfen\n}\n", task: "Prüfe fehlenden, leeren, zu langen und gültigen Titel. Sende für Fehler 400 mit einer stabilen Kennung.", marker: "typeof|trim\\(|length", checks: ["Vier Eingaben werden tatsächlich getestet.", "Ungültige Daten erreichen die Datenbank nicht."] },
  { id: "express-errors", module: "11 · Express beherrschen", title: "Asynchrone Fehler kontrolliert beantworten", language: "javascript", objective: "Du trennst interne Fehlerdetails von der öffentlichen HTTP-Antwort.", explanation: "Ein Datenbankfehler darf nicht als Stacktrace beim Client landen. In Express 5 gelangen geworfene Fehler aus async-Handlern an die Fehler-Middleware. Diese steht nach den Routen, protokolliert intern und antwortet allgemein.", flow: ["async-Route wirft Fehler", "Fehler-Middleware", "503 ohne Geheimnisse"], example: "app.use((error, _req, res, _next) => {\n  console.error(error);\n  res.status(503).json({ error: 'temporarily_unavailable' });\n});", note: "Ein Fehler wird nur einmal beantwortet; nach res.json darf kein zweiter Header gesendet werden.", starter: "app.use((error, req, res, next) => {\n  // sicher antworten\n});\n", task: "Simuliere einen Datenbankausfall und prüfe, dass der Client 503 ohne interne Fehlermeldung erhält.", marker: "app\\.use|res\\.status\\(503", checks: ["Fehler wird intern protokolliert.", "Antwort enthält kein Passwort und keinen Stacktrace."] },
  { id: "database-schema", module: "12 · Daten zuverlässig speichern", title: "Tabellen und Beziehungen für Aufgaben entwerfen", language: "sql", objective: "Du definierst Aufgaben, Nutzerbezug und Datenregeln in PostgreSQL.", explanation: "Ein Schema legt Tabellen und Beziehungen fest. Ein Fremdschlüssel verbindet eine Aufgabe mit ihrem Besitzer; NOT NULL und CHECK verhindern ungültige Zustände auch außerhalb der API.", flow: ["Fachregel", "Tabellenschema", "Datenbank erzwingt Grenze"], example: "CREATE TABLE tasks (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  owner_id bigint NOT NULL REFERENCES users(id),\n  title text NOT NULL CHECK (length(trim(title)) > 0)\n);", note: "Die Datenbankregel ergänzt die API-Prüfung und gilt für jeden Schreibweg.", starter: "CREATE TABLE tasks (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY\n);\n", task: "Ergänze Besitzer, Titel und eine Regel gegen leere Titel. Prüfe einen gültigen und einen ungültigen INSERT.", marker: "REFERENCES|CHECK|NOT NULL", checks: ["Aufgabe hat eine Besitzerbeziehung.", "Leerer Titel wird von der Datenbank abgewiesen."] },
  { id: "migrations", module: "12 · Daten zuverlässig speichern", title: "Schemaänderungen als Migration durchführen", language: "sql", objective: "Du änderst eine bestehende Tabelle nachvollziehbar ohne Datenverlust.", explanation: "Eine Migration ist eine versionierte Änderung am Datenbankschema. Ergänze eine Spalte mit einem sicheren Standardwert, prüfe alte Zeilen und dokumentiere, wie du eine fehlerhafte Änderung zurücknehmen würdest.", flow: ["Alter Datenstand", "ALTER TABLE", "Alte + neue Zeilen prüfen"], example: "ALTER TABLE tasks ADD COLUMN done boolean NOT NULL DEFAULT false;\nSELECT id, done FROM tasks;", note: "Ein Standardwert versorgt vorhandene Zeilen, bevor die Anwendung das neue Feld verwendet.", starter: "ALTER TABLE tasks ADD COLUMN done boolean NOT NULL DEFAULT false;\n-- vorhandene Zeilen prüfen\n", task: "Führe die Änderung an einer Testdatenbank aus, prüfe alte und neue Aufgaben und notiere eine Rücknahme.", marker: "ALTER TABLE|SELECT", checks: ["Vorhandene Aufgaben bleiben lesbar.", "Rücknahme und Datensicherung sind beschrieben."] },
  { id: "transactions", module: "12 · Daten zuverlässig speichern", title: "Mehrere Änderungen atomar ausführen", language: "javascript", objective: "Du nutzt eine Datenbanktransaktion für zusammengehörige Änderungen.", explanation: "Eine Transaktion bestätigt mehrere Änderungen gemeinsam oder verwirft sie gemeinsam. Verwende denselben Datenbank-Client für BEGIN, alle Abfragen und COMMIT; bei einem Fehler folgt ROLLBACK.", flow: ["BEGIN", "Alle Abfragen", "COMMIT oder ROLLBACK"], example: "const client = await pool.connect();\ntry {\n  await client.query('BEGIN');\n  // zusammengehörige Änderungen\n  await client.query('COMMIT');\n} catch (error) { await client.query('ROLLBACK'); throw error; }\nfinally { client.release(); }", note: "Ein Pool-Client bleibt bis zur Freigabe belegt; gib ihn auch nach Fehlern frei.", starter: "const client = await pool.connect();\ntry {\n  await client.query('BEGIN');\n  // Änderungen\n} finally { client.release(); }\n", task: "Speichere Aufgabe und Ereigniseintrag in einer Transaktion. Erzwinge einen Fehler und prüfe, dass beides zurückgerollt wird.", marker: "BEGIN|COMMIT|ROLLBACK", checks: ["Alle Abfragen nutzen denselben Client.", "Fehler hinterlässt keinen halben Zustand."] },
  { id: "authentication-session", module: "13 · Identität und Rechte", title: "Anmeldung und Sitzung sauber unterscheiden", language: "plaintext", objective: "Du zeichnest den Weg von Anmeldung zu einer geschützten Anfrage.", explanation: "Authentifizierung prüft eine Identität; Autorisierung prüft eine Berechtigung. Eine Sitzung verbindet spätere Anfragen mit einer zuvor geprüften Anmeldung. Passwörter gehören nie in Logs oder Antworten.", flow: ["Anmeldung prüfen", "Sitzung ausstellen", "Anfrage + Recht prüfen"], example: "POST /login → Identität geprüft\nGET /me → Sitzung gelesen\nGET /tasks/7 → Besitzer geprüft", note: "Eine gültige Sitzung allein erlaubt noch keinen Zugriff auf fremde Aufgaben.", starter: "Anmeldung: \nSitzung: \nBerechtigungsprüfung: \nFehlerfälle: \n", task: "Skizziere Anmeldung, Sitzung, Abmeldung und einen abgewiesenen Fremdzugriff für die Aufgaben-API.", marker: "Anmeldung:|Sitzung:", checks: ["Identität und Recht sind getrennt.", "Fremde Aufgabe wird serverseitig abgewiesen."] },
  { id: "authorization", module: "13 · Identität und Rechte", title: "Besitzrechte in jeder Route prüfen", language: "javascript", objective: "Du verhinderst, dass eine gültige Anmeldung fremde Daten freigibt.", explanation: "Objektbezogene Autorisierung vergleicht die angemeldete Kennung mit dem Besitzer der angefragten Aufgabe. Der Client darf die Besitzerkennung nicht frei vorgeben; der Server verwendet die geprüfte Sitzung.", flow: ["Sitzungskennung", "Aufgabe + owner_id", "Antwort oder 403/404"], example: "const task = await repository.findById(taskId);\nif (!task || task.owner_id !== req.user.id) return res.sendStatus(404);\nreturn res.json(task);", note: "Ein Fremdzugriff wird geprüft, auch wenn die Oberfläche den Link nicht anzeigt.", starter: "app.get('/tasks/:id', async (req, res) => {\n  // Besitzer aus geprüfter Sitzung vergleichen\n});\n", task: "Teste eigene, fremde und fehlende Aufgabe mit zwei Testnutzern. Prüfe auch PATCH und DELETE.", marker: "owner_id|req\\.user|res\\.sendStatus", checks: ["Alle schreibenden Routen prüfen Besitzrechte.", "Fremde Daten erscheinen weder in Antwort noch Log."] },
  { id: "api-contract-tests", module: "14 · Qualität und Betrieb", title: "API-Vertrag mit echten HTTP-Tests sichern", language: "javascript", objective: "Du prüfst Status, Header und JSON statt nur den Quelltext.", explanation: "Ein Vertragstest ruft eine Route wie ein Client auf. Der eingebaute Node-Test-Runner kann fetch gegen einen lokalen Testserver verwenden; prüfe Erfolg, falsche Eingabe und fehlende Berechtigung.", flow: ["Testserver starten", "HTTP-Anfrage senden", "Status + JSON vergleichen"], example: "import test from 'node:test';\nimport assert from 'node:assert/strict';\ntest('health answers', async () => {\n  const response = await fetch(baseUrl + '/health');\n  assert.equal(response.status, 200);\n});", note: "Ein Test muss den Server starten und am Ende schließen; baseUrl stammt aus dem lokalen Testaufbau.", starter: "import test from 'node:test';\nimport assert from 'node:assert/strict';\n// HTTP-Test ergänzen\n", task: "Teste GET /health, ungültiges POST /tasks und fremdes GET /tasks/:id über HTTP.", marker: "node:test|fetch\\(|assert\\.equal", checks: ["Testserver wird nach jedem Lauf geschlossen.", "Status und Antwortinhalt werden geprüft."] },
  { id: "observability", module: "14 · Qualität und Betrieb", title: "Logs, Metriken und Health-Checks trennen", language: "plaintext", objective: "Du erkennst einen Ausfall, ohne geheime Daten zu protokollieren.", explanation: "Logs beschreiben einzelne Ereignisse, Metriken zeigen Mengen und Zeiten, Health-Checks beantworten Betriebsfragen. Eine lebende App kann dennoch keine Datenbank erreichen; prüfe Prozess und Abhängigkeiten getrennt.", flow: ["Anfrage mit Kennung", "Log + Dauer", "Health und Alarm"], example: "GET /health/live → Prozess läuft\nGET /health/ready → Datenbank erreichbar\nLog: request_id, route, status, dauer", note: "Passwörter, Zugangstoken und vollständige persönliche Daten gehören nicht in Logs.", starter: "Liveness: \nReadiness: \nLogfelder: \nAlarm bei: \n", task: "Erstelle zwei Health-Routen und eine Logliste für deine API. Simuliere einen Datenbankausfall und prüfe den Unterschied.", marker: "Liveness:|Readiness:", checks: ["Liveness und Readiness beantworten verschiedene Fragen.", "Logs enthalten keine Geheimnisse."] },
];

